import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Loader2, Play, Pause, Upload, Cuboid, Trash2, SlidersHorizontal, Check, Circle, Square } from 'lucide-react';
import Scene from './components/Scene';
import { extractFrames } from './services/video';
import { processDepth } from './services/depth';
import { SplatFrame } from './types';

export default function App() {
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState('');
  const [frames, setFrames] = useState<SplatFrame[]>([]);
  const [currentFrameIndex, setCurrentFrameIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [selectedVideo, setSelectedVideo] = useState<string | null>(null);
  const [isPrompting, setIsPrompting] = useState(false);
  const [targetFrameCount, setTargetFrameCount] = useState(48);

  const [pointSize, setPointSize] = useState(2.0);
  const [opacity, setOpacity] = useState(1.0);
  const [depthScale, setDepthScale] = useState(1.5);
  const [brightness, setBrightness] = useState(1.2);
  const [saturation, setSaturation] = useState(1.1);
  const [isGlowEnabled, setIsGlowEnabled] = useState(false);
  const [fps, setFps] = useState(12);

  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const resolution = 160;
  const framesRef = useRef<SplatFrame[]>([]);
  const playbackRef = useRef<any>(null);

  const handleVideoSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (!media) return;
      const videoDataUrl = `data:${media.mimeType};base64,${media.base64}`;
      setSelectedVideo(videoDataUrl);
      setIsPrompting(true);
    } catch (err) {
      console.error(err);
    }
  };

  const startReconstruction = async () => {
    if (!selectedVideo) return;
    setIsPrompting(false);
    setIsProcessing(true);
    setFrames([]);
    setProgress(0);

    try {
      setStatus('Extracting Frames...');
      const extracted = await extractFrames(selectedVideo, targetFrameCount);
      const processed: SplatFrame[] = [];
      for (let i = 0; i < extracted.length; i++) {
        setStatus(`Depth Mapping ${i + 1}/${extracted.length}`);
        setProgress(Math.round((i / extracted.length) * 100));
        const depthData = await processDepth(extracted[i]);
        processed.push({ id: i, image: extracted[i], depth: depthData });
      }
      framesRef.current = processed;
      setFrames(processed);
      setIsProcessing(false);
      setIsPlaying(true);
      setStatus('');
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      setStatus('Processing failed');
    }
  };

  const startRecording = useCallback(() => {
    const canvas = document.querySelector('canvas');
    if (!canvas) {
      setStatus('Canvas not found');
      return;
    }

    chunksRef.current = [];
    const stream = canvas.captureStream(30); // 30 FPS
    const recorder = new MediaRecorder(stream, {
      mimeType: 'video/webm;codecs=vp9', // Higher quality capture
      videoBitsPerSecond: 12000000 // 12 Mbps for high fidelity
    });

    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };

    recorder.onstop = async () => {
      const blob = new Blob(chunksRef.current, { type: 'video/webm' });
      setStatus('Saving to Grid...');

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        try {
          // Flow.save handles the conversion to MP4 internally for video items
          await Flow.save({
            base64,
            mimeType: 'video/mp4', // Signal that this is video content
            name: `Volumetric_Recording_${Date.now()}`
          });
          setStatus('Saved!');
          setTimeout(() => setStatus(''), 2000);
        } catch (error) {
          console.error('Flow save error:', error);
          setStatus('Save Failed');
        }
      };
      reader.readAsDataURL(blob);
    };

    mediaRecorderRef.current = recorder;
    recorder.start();
    setIsRecording(true);
    setStatus('Recording...');
  }, []);

  const stopRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  }, []);

  useEffect(() => {
    if (isPlaying && frames.length > 0) {
      playbackRef.current = setInterval(() => {
        setCurrentFrameIndex(p => (p + 1) % frames.length);
      }, 1000 / fps);
    } else {
      if (playbackRef.current) clearInterval(playbackRef.current);
    }
    return () => {
      if (playbackRef.current) clearInterval(playbackRef.current);
    };
  }, [isPlaying, frames.length, fps]);

  const hasData = frames.length > 0;

  return (
    <div className="relative w-full h-full bg-zinc-950 text-white overflow-hidden">
      <div className="absolute inset-0 z-0">
        <Scene
          frameIndex={currentFrameIndex}
          framesRef={framesRef}
          pointSize={pointSize}
          opacity={opacity}
          depthScale={depthScale}
          brightness={brightness}
          saturation={saturation}
          isGlowEnabled={isGlowEnabled}
          resolution={resolution}
        />
      </div>

      <div className="absolute inset-0 z-10 pointer-events-none flex flex-col justify-between p-6">
        <div className="flex justify-between items-start pointer-events-auto">
          <div /> {/* Layout spacer */}
          <div className="flex gap-2">
            {hasData && (
              <>
                <button
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-3 border border-white transition-colors pointer-events-auto ${showSettings ? 'bg-white text-black' : 'bg-zinc-950/90 hover:bg-white/10'}`}
                >
                  <SlidersHorizontal className="w-5 h-5" />
                </button>
                <button
                  onClick={handleVideoSelect}
                  className="px-6 py-2.5 bg-white text-black border border-white hover:bg-zinc-200 font-bold flex items-center gap-2 pointer-events-auto transition-all active:translate-y-0.5"
                >
                  <Upload className="w-4 h-4" />
                  REPLACE VIDEO
                </button>
              </>
            )}
          </div>
        </div>

        {!hasData && !isProcessing && !isPrompting && (
          <div className="flex-1 flex items-center justify-center pointer-events-auto">
            <button
              onClick={handleVideoSelect}
              className="group flex flex-col items-center gap-6 bg-white text-black p-16 border-4 border-white hover:bg-zinc-200 transition-all active:translate-y-1"
            >
              <div className="p-6 bg-black text-white">
                <Upload size={48} />
              </div>
              <div className="text-center">
                <h2 className="text-3xl font-black tracking-tighter uppercase">Import Video</h2>
                <p className="text-xs font-bold opacity-60 uppercase tracking-widest">Generate Volumetric 3D</p>
              </div>
            </button>
          </div>
        )}

        {isPrompting && (
          <div className="absolute inset-0 bg-black/90 z-[100] flex items-center justify-center pointer-events-auto">
            <div className="bg-zinc-950 border-2 border-white p-12 w-[400px] aspect-square flex flex-col justify-between animate-in">
              <div className="text-center pt-4">
                <h3 className="text-2xl font-black uppercase tracking-tighter">Number of frames to extract</h3>
              </div>
              <div className="space-y-8">
                <div className="flex justify-between items-end border-b border-white pb-2">
                  <span className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Selected Density</span>
                  <span className="text-6xl font-black text-white leading-none">{targetFrameCount}</span>
                </div>
                <div className="pb-8">
                  <input
                    type="range"
                    min="8"
                    max="128"
                    step="8"
                    value={targetFrameCount}
                    onChange={(e) => setTargetFrameCount(Number(e.target.value))}
                    className="accent-white w-full h-1"
                  />
                </div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setIsPrompting(false)}
                  className="flex-1 py-4 px-6 border border-white hover:bg-white hover:text-black font-black transition-all text-xs uppercase"
                >
                  Cancel
                </button>
                <button 
                  onClick={startReconstruction}
                  className="flex-[2] py-4 px-6 bg-white text-black border border-white hover:bg-zinc-200 font-black flex items-center justify-center gap-2 transition-all text-xs uppercase"
                >
                  <Check size={20} />
                  Process
                </button>
              </div>
            </div>
          </div>
        )}

        {isProcessing && (
          <div className="absolute inset-0 bg-black/95 z-50 flex items-center justify-center pointer-events-auto">
            <div className="text-center space-y-8 max-w-xs w-full px-6">
              <Loader2 className="w-20 h-20 text-white animate-spin mx-auto" />
              <div className="space-y-4">
                <h2 className="text-2xl font-black tracking-tighter uppercase">{status}</h2>
                <div className="w-full bg-zinc-900 border border-white h-4 overflow-hidden">
                  <div className="h-full bg-white transition-all duration-300" style={{ width: `${progress}%` }} />
                </div>
                <p className="text-[10px] font-black tracking-widest text-zinc-500 uppercase">{progress}% Complete</p>
              </div>
            </div>
          </div>
        )}

        {status && !isProcessing && (
          <div className="absolute inset-x-0 bottom-40 flex justify-center z-40 pointer-events-none">
            <div className="bg-white text-black px-8 py-3 font-black uppercase tracking-tighter border-2 border-black">
              {status}
            </div>
          </div>
        )}

        <div className="flex flex-col gap-4 items-center mb-4 w-full">
          {hasData && (
            <div className="flex items-center gap-4 w-full max-w-2xl pointer-events-auto">
              <div className="bg-zinc-950/90 border border-white px-8 py-6 flex-1 flex items-center gap-8">
                <button
                  onClick={() => setIsPlaying(!isPlaying)}
                  className="w-14 h-14 flex items-center justify-center bg-white text-black hover:bg-zinc-200 active:translate-y-0.5 transition-all"
                >
                  {isPlaying ? <Pause size={28} fill="currentColor" /> : <Play size={28} className="ml-1" fill="currentColor" />}
                </button>
                <div className="flex-1 flex flex-col gap-4">
                  <div className="flex justify-between items-end border-b border-white/20 pb-1">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Timeline</span>
                      <span className="text-xs font-black text-white">[{currentFrameIndex + 1} / {frames.length}]</span>
                    </div>
                    <div className="flex flex-col items-end">
                      <span className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">Temporal</span>
                      <span className="text-xs font-black text-white">{fps} FPS</span>
                    </div>
                  </div>
                  <div className="relative group h-6 flex items-center">
                    <input
                      type="range"
                      min="0"
                      max={frames.length - 1}
                      value={currentFrameIndex}
                      onChange={(e) => { setIsPlaying(false); setCurrentFrameIndex(Number(e.target.value)); }}
                      className="relative z-10 w-full accent-white"
                    />
                  </div>
                </div>
                <button onClick={() => setFrames([])} className="p-3 text-zinc-500 hover:text-white transition-all hover:bg-white/10" title="Clear Reconstruction">
                  <Trash2 size={24} />
                </button>
              </div>
              <button
                onClick={isRecording ? stopRecording : startRecording}
                className={`w-20 h-20 flex items-center justify-center border-2 border-white transition-all active:translate-y-1 ${
                  isRecording 
                    ? 'bg-red-600 text-white animate-pulse' 
                    : 'bg-white text-black hover:bg-zinc-200'
                }`}
                title={isRecording ? "Stop Recording" : "Record Scene"}
              >
                {isRecording ? <Square size={32} fill="currentColor" /> : <Circle size={32} fill="currentColor" />}
              </button>
            </div>
          )}
        </div>
      </div>

      {showSettings && (
        <div className="absolute top-24 right-6 z-20 w-80 bg-zinc-950 border border-white p-8 shadow-2xl pointer-events-auto max-h-[70vh] overflow-y-auto custom-scrollbar">
          <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em] mb-8">Visual System Config</h3>
          <div className="space-y-8">
            <div className="flex justify-between items-center bg-white/5 p-4 border border-white/10">
              <label className="text-[10px] font-black text-white uppercase tracking-widest">Particle Glow</label>
              <button 
                onClick={() => setIsGlowEnabled(!isGlowEnabled)}
                className={`w-12 h-6 border border-white flex items-center px-1 transition-all ${isGlowEnabled ? 'bg-white' : 'bg-black'}`}
              >
                <div className={`w-4 h-4 transition-all ${isGlowEnabled ? 'bg-black translate-x-6' : 'bg-white'}`} />
              </button>
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-white uppercase tracking-widest flex justify-between">Brightness <span>{brightness.toFixed(1)}x</span></label>
              <input type="range" min="0.5" max="3" step="0.1" value={brightness} onChange={e => setBrightness(Number(e.target.value))} className="accent-white" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black text-white uppercase tracking-widest flex justify-between">Color Saturation <span>{saturation.toFixed(1)}x</span></label>
              <input type="range" min="0.1" max="2.5" step="0.1" value={saturation} onChange={e => setSaturation(Number(e.target.value))} className="accent-white" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black text-white uppercase tracking-widest flex justify-between">Voxel Density <span>{pointSize.toFixed(1)}</span></label>
              <input type="range" min="0.5" max="8" step="0.5" value={pointSize} onChange={e => setPointSize(Number(e.target.value))} className="accent-white" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black text-white uppercase tracking-widest flex justify-between">Extrusion Depth <span>{depthScale.toFixed(1)}x</span></label>
              <input type="range" min="0.5" max="5" step="0.1" value={depthScale} onChange={e => setDepthScale(Number(e.target.value))} className="accent-white" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black text-white uppercase tracking-widest flex justify-between">Temporal FPS <span>{fps}</span></label>
              <input type="range" min="1" max="30" step="1" value={fps} onChange={e => setFps(Number(e.target.value))} className="accent-white" />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

