export interface SplatFrame {
  id: number;
  image: string; // dataUrl
  depth: Float32Array; // depth map values
}

export async function extractFrames(videoUrl: string, count: number): Promise<string[]> {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    video.src = videoUrl;
    video.crossOrigin = 'anonymous';
    video.muted = true;
    video.playsInline = true;

    video.onloadedmetadata = async () => {
      const frames: string[] = [];
      const duration = video.duration;
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      // 320x320 matches the depth model input resolution
      canvas.width = 320;
      canvas.height = 320;

      for (let i = 0; i < count; i++) {
        const time = (duration / count) * i;
        video.currentTime = time;

        await new Promise((r) => {
          const onSeeked = () => {
            video.removeEventListener('seeked', onSeeked);
            r(true);
          };
          video.addEventListener('seeked', onSeeked);
        });

        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          frames.push(canvas.toDataURL('image/jpeg', 0.8));
        }
      }
      resolve(frames);
    };

    video.onerror = (e) => reject(new Error('Video failed to load'));
  });
}

import { pipeline, env } from '@huggingface/transformers';

// Required for sandboxed iframe runtime
env.allowLocalModels = false;
env.useBrowserCache = false;

let depthPipeline: any = null;

export async function processDepth(imageUrl: string): Promise<Float32Array> {
  if (!depthPipeline) {
    const hasWebGPU = !!navigator.gpu;
    depthPipeline = await pipeline('depth-estimation', 'onnx-community/depth-anything-v2-small', {
      device: hasWebGPU ? 'webgpu' : 'wasm',
      dtype: hasWebGPU ? 'fp16' : 'q8',
    });
  }

  const result = await depthPipeline(imageUrl);
  const depthData = result.depth.data;

  // Normalize depth data to 0.0 - 1.0 range
  let min = Infinity;
  let max = -Infinity;
  for (let i = 0; i < depthData.length; i++) {
    const v = depthData[i];
    if (v < min) min = v;
    if (v > max) max = v;
  }

  const range = max - min || 1;
  const normalized = new Float32Array(depthData.length);
  for (let i = 0; i < depthData.length; i++) {
    normalized[i] = (depthData[i] - min) / range;
  }

  return normalized;
}

import React, { useRef, useMemo, useEffect, useState } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera } from '@react-three/drei';
import * as THREE from 'three';
import { SplatFrame } from '../types';

interface PointCloudProps {
  frame: SplatFrame;
  pointSize: number;
  opacity: number;
  depthScale: number;
  brightness: number;
  saturation: number;
  isGlowEnabled: boolean;
  resolution: number;
}

function PointCloud({ frame, pointSize, opacity, depthScale, brightness, saturation, isGlowEnabled, resolution }: PointCloudProps) {
  const pointsRef = useRef<THREE.Points>(null!);
  const [texture, setTexture] = useState<THREE.Texture | null>(null);

  // Constants
  const srcSize = 320;
  const XY_SPREAD = 4.5;

  // Static buffers
  const { positions, colors } = useMemo(() => {
    const res = Math.max(16, Math.min(320, resolution));
    const numPoints = res * res;
    return {
      positions: new Float32Array(numPoints * 3),
      colors: new Float32Array(numPoints * 3)
    };
  }, [resolution]);

  // Create sprite texture - softer falloff for glow, harder for solid
  useEffect(() => {
    const canvasTex = document.createElement('canvas');
    canvasTex.width = 64;
    canvasTex.height = 64;
    const ctxTex = canvasTex.getContext('2d')!;
    const grad = ctxTex.createRadialGradient(32, 32, 0, 32, 32, 32);
    grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
    grad.addColorStop(0.7, 'rgba(255, 255, 255, 0.2)');
    grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctxTex.fillStyle = grad;
    ctxTex.fillRect(0, 0, 64, 64);
    const tex = new THREE.CanvasTexture(canvasTex);
    setTexture(tex);
    return () => tex.dispose();
  }, []);

  // Update logic
  useEffect(() => {
    const img = new Image();
    img.src = frame.image;
    img.onload = () => {
      const res = Math.max(16, Math.min(320, resolution));
      const step = srcSize / res;

      const sampleCanvas = document.createElement('canvas');
      sampleCanvas.width = res;
      sampleCanvas.height = res;
      const sCtx = sampleCanvas.getContext('2d')!;
      sCtx.drawImage(img, 0, 0, res, res);
      const pixelData = sCtx.getImageData(0, 0, res, res).data;

      const posAttr = pointsRef.current.geometry.attributes.position;
      const colAttr = pointsRef.current.geometry.attributes.color;

      for (let y = 0; y < res; y++) {
        for (let x = 0; x < res; x++) {
          const idx = y * res + x;

          posAttr.setXYZ(idx, (x / res - 0.5) * XY_SPREAD, -(y / res - 0.5) * XY_SPREAD, 0);

          const srcX = Math.min(Math.floor(x * step), srcSize - 1);
          const srcY = Math.min(Math.floor(y * step), srcSize - 1);
          const depth = frame.depth[srcY * srcSize + srcX];

          posAttr.setZ(idx, (depth - 0.5) * depthScale * 4);

          // Get base color
          let r = pixelData[idx * 4] / 255;
          let g = pixelData[idx * 4 + 1] / 255;
          let b = pixelData[idx * 4 + 2] / 255;

          // Apply saturation enhancement
          const gray = (r + g + b) / 3;
          r = gray + (r - gray) * saturation;
          g = gray + (g - gray) * saturation;
          b = gray + (b - gray) * saturation;

          // Apply brightness boost
          r *= brightness;
          g *= brightness;
          b *= brightness;

          // Clamp for normal blending to prevent blow-out, allow higher for glow
          const maxVal = isGlowEnabled ? 1.5 : 1.0;
          colAttr.setXYZ(idx, Math.min(maxVal, r), Math.min(maxVal, g), Math.min(maxVal, b));
        }
      }
      posAttr.needsUpdate = true;
      colAttr.needsUpdate = true;
    };
  }, [frame.id, depthScale, brightness, saturation, resolution, isGlowEnabled]);

  if (!texture) return null;

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={positions.length / 3}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={colors.length / 3}
          array={colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={pointSize / 50}
        vertexColors
        transparent={true}
        opacity={opacity}
        map={texture}
        alphaTest={isGlowEnabled ? 0.01 : 0.4}
        depthWrite={!isGlowEnabled}
        depthTest={true}
        blending={isGlowEnabled ? THREE.AdditiveBlending : THREE.NormalBlending}
      />
    </points>
  );
}

export default function Scene({ frameIndex, framesRef, pointSize, opacity, depthScale, brightness, saturation, isGlowEnabled, resolution }: any) {
  const currentFrame = framesRef.current[frameIndex];

  return (
    <div className="w-full h-full">
      <Canvas gl={{ antialias: true, preserveDrawingBuffer: true, toneMapping: THREE.NoToneMapping }}>
        <color attach="background" args={['#09090b']} />
        <PerspectiveCamera makeDefault position={[0, 0, 8]} fov={50} />
        <ambientLight intensity={1.5} />
        {currentFrame && (
          <PointCloud
            frame={currentFrame}
            pointSize={pointSize}
            opacity={opacity}
            depthScale={depthScale}
            brightness={brightness}
            saturation={saturation}
            isGlowEnabled={isGlowEnabled}
            resolution={resolution}
          />
        )}
        <OrbitControls makeDefault enableDamping dampingFactor={0.1} />
      </Canvas>
    </div>
  );
}
